{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "blocks/3/items/3 の hs",
      "detail": "std では「危険運転致死」であるのに対し、hs では「酒に酔って車を運転し、人をひいて死なせた場合」と「酒に酔って」に限定されている。薬物など他の危険運転のケースが抜けている。",
      "fix": "「危険な運転で人を死なせた場合」などに直す。"
    },
    {
      "type": "名前と数字",
      "where": "blocks/4/text の hs",
      "detail": "std に「18歳」という年齢の記載はないが、hs で「（18歳以上）」と補足されている。中身のずれおよび数字・情報の追加にあたる。",
      "fix": "「投票できる人」とするか、std に合わせて年齢の数字を入れないようにする。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/5/text の hs",
      "detail": "std では「法令に従い公平誠実に職務を行い…秘密を漏らしてはなりません」や「法令の解釈や訴訟手続に関する判断は裁判官だけで行います」と複数の情報があるが、hs では秘密を守る義務しか触れられておらず、情報が大きく抜けている。",
      "fix": "std の内容に合わせて、法律に従うことや裁判官との役割分担についても書き加える。"
    }
  ]
}
